#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

long long pow_mod(long long base, int exp) {
    long long result = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

void precomputeFactorials(vector<long long>& fact, vector<long long>& invFact, int n) {
    fact[0] = 1;
    for (int i = 1; i <= n; i++) {
        fact[i] = (fact[i - 1] * i) % MOD;
    }
    invFact[n] = pow_mod(fact[n], (int)(MOD - 2));
    for (int i = n - 1; i >= 0; i--) {
        invFact[i] = (invFact[i + 1] * (i + 1)) % MOD;
    }
}

long long nCr(int n, int r, const vector<long long>& fact, const vector<long long>& invFact) {
    if (n < r) return 0;
    return (((fact[n] * invFact[r]) % MOD) * invFact[n - r]) % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long tmp;
    cin >> n >> tmp;
    if (n <= tmp) {
        cout << 0 << "\n";
        return 0;
    }
    int k = (int)tmp;
    vector<long long> fact(400001);
    vector<long long> invFact(400001);
    precomputeFactorials(fact, invFact, 400000);
    long long totalComb = nCr(n, n - k, fact, invFact);
    long long answer = 0;
    int sign = 1;
    for (int i = n - k; i >= 1; i--) {
        long long comb = nCr(n - k, i, fact, invFact);
        long long val = pow_mod(i, n);
        answer = (answer + sign * comb % MOD * val % MOD) % MOD;
        sign *= -1;
    }
    answer = (answer * totalComb) % MOD;
    if (k != 0) answer = (answer * 2) % MOD;
    cout << (answer + MOD) % MOD << "\n";
    return 0;
}

